INSERT INTO agent_debug_trace_control (
    id, created_by_user_id, scope_user_id, scope_run_id, scope_starts_at, scope_ends_at,
    enabled, created_at, disabled_at
)
VALUES (
    #{id}, #{createdByUserId}, #{scopeUserId}, #{scopeRunId}, #{scopeStartsAt}, #{scopeEndsAt},
    #{enabled}, #{createdAt}, #{disabledAt}
)

INSERT INTO agent_debug_trace_capture (
    id, control_id, user_id, run_id, event_type, content, content_sha256,
    content_expires_at, content_deleted_at, created_at
)
VALUES (
    #{id}, #{controlId}, #{userId}, #{runId}, #{eventType}, #{content}, #{contentSha256},
    #{contentExpiresAt}, #{contentDeletedAt}, #{createdAt}
)

mapper.update:
UPDATE agent_debug_trace_capture
SET content = NULL,
    content_deleted_at = #{now}
WHERE content IS NOT NULL
  AND content_expires_at <= #{now}

UPDATE agent_debug_trace_capture
SET content_expires_at = #{expiresAt}
WHERE run_id = #{runId}
  AND content IS NOT NULL
